package in.jharkhand.civic.service;import in.jharkhand.civic.port.NotificationService;import in.jharkhand.civic.repository.JsonStore;import org.springframework.stereotype.Component;import java.time.Instant;import java.util.*;
@Component public class JsonNotificationService implements NotificationService{private final JsonStore s;private final IdService ids;public JsonNotificationService(JsonStore s,IdService i){this.s=s;this.ids=i;}public void notifyUser(String userId,String title,String message){s.add("notifications.json",Map.of("id",ids.id("notification"),"userId",userId,"title",title,"message",message,"read",false,"createdAt",Instant.now().toString()));}}
